def _unique_list(value, label):
    if not isinstance(value, list):
        raise ValueError('%s must be a list' % label)
    seen = set()
    for item in value:
        if not isinstance(item, str) or isinstance(item, bool):
            raise ValueError('%s entries must be strings' % label)
        if item in seen:
            raise ValueError('%s contains duplicate value: %s' % (label, item))
        seen.add(item)
    return value


